import os

def write_to_file(content, filename='myfile.txt'):
    try:
        with open(filename, 'w') as f:
            f.write(content)
    except IOError as e:
        print(f"An error occurred while writing to the file: {e}")

def read_from_file(filename='myfile.txt'):
    try:
        with open(filename, 'r') as f:
            return f.read()
    except IOError as e:
        print(f"An error occurred while reading from the file: {e}")
        return None

def delete_file(filename='myfile.txt'):
    try:
        os.remove(filename)
    except OSError as e:
        print(f"An error occurred while deleting the file: {e}")
